UPDATE `plot`
user_id = #{userId}, farm_id = #{farmId}, plot_name = #{plotName}, plot_code = #{plotCode}, crop_image = #{cropImage}, type = #{type}, area = #{area}, area_unit = #{areaUnit}, address = #{address}, longitude = #{longitude}, latitude = #{latitude}, boundary_points = #{boundaryPoints,typeHandler=com.smart_plant.smart_plant.typehandler.PlotBoundaryPointListTypeHandler}, status = #{status}, remark = #{remark},
WHERE id = #{id}

mapper.select:
SELECT 
FROM `plot` p



        AND p.plot_name LIKE CONCAT('%', #{plotName}, '%')


        AND p.plot_code LIKE CONCAT('%', #{plotCode}, '%')


        AND p.farm_id = #{farmId}


        AND p.user_id = #{userId}


        AND p.type = #{type}


        AND p.status = #{status}


ORDER BY p.id DESC

SELECT COUNT(1)
FROM `plot`
WHERE user_id = #{userId}
  AND plot_code = #{plotCode}

    AND id != #{excludeId}
